def max_cookies(n, k, a, b):
    cookies = 0
    magic_used = False

    for i in range(n):
        if b[i] >= a[i]:
            cookies += b[i] // a[i]
        else:
            if not magic_used:
                magic_needed = a[i] - b[i]
                if k >= magic_needed:
                    cookies += (b[i] + k) // a[i]
                    k -= magic_needed
                    magic_used = True
                else:
                    cookies += (b[i] + k) // a[i]
                    k = 0
            else:
                cookies += b[i] // a[i]

    return cookies

